var t=`0376-waterzooi`;var n=`world-0376`;var o=`BE`;var a=`western-europe`;var s=4;var r=63;var m={en:`Waterzooi`,ua:`Ватерзой`};var h={en:`A traditional Belgium dish made with yellow onion, carrot, celery stalk, thyme. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Бельгія. Основні інгредієнти: жовта цибуля, морква, стебло селери, чебрець. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`carrot`,180,`g`],[`celery-stalk`,140,`g`],[`unsalted-butter`,55,`g`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 30 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 30 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:30,i:[[`chicken-stock`,950,`ml`],[`dry-white-wine`,150,`ml`],[`thyme`,2,`sprig`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 17 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 17 хвилин до готовності й м’якості.`,t:[`poaching`],m:17,i:[[`chicken-thigh`,670,`g`],[`potato`,300,`g`]]},{en:`Whisk the yolks and cream with lemon, then temper with hot broth and stir into the stew off the heat; do not boil after thickening.`,ua:`Збийте жовтки з вершками та лимоном, темперуйте гарячим бульйоном і введіть у рагу поза вогнем; після загущення не кип’ятіть.`,t:[`mixing`],m:5,i:[[`egg-yolk`,2,`pcs`],[`heavy-cream`,175,`ml`],[`lemon-juice`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var g={slug:t,id:n,country:`BE`,region:a,servings:4,minutes:63,title:m,text:h,steps:l};export{o as country,g as default,n as id,r as minutes,a as region,s as servings,t as slug,l as steps,h as text,m as title};